    public abstract class RuntimeRole : IBindPlayer, IGameOperator, ILifespan
    {
        public DefinedRole Definition { get; }
        public Player MyPlayer { get; }
        public bool AmOwner => MyPlayer.AmOwner;

        // 能力列表
