        {
            message = "日志值为null";
        }
        string logLine = $"[{DateTime.Now:yyyy/M/d HH:mm:ss}]: \"{message}\"";
        AppendLog(logLine);
    }
    public static void LogError(string message = "undefined", string reason = "undefined")
    {
        if (message == null)
        {
